from .errors import LexError


@dataclass(frozen=True)
class Token:
    kind: str
    value: object
    position: int


KEYWORDS = {"true", "false", "and", "or", "not"}
ESCAPES = {
    "n": "\n",
    "t": "\t",
    "r": "\r",
    '"': '"',
    "\\": "\\",
}


def tokenize(source: str) -> list[Token]:
    tokens: list[Token] = []
    i = 0
    n = len(source)

    while i < n:
        ch = source[i]

        if ch.isspace():
            i += 1
            continue

        if ch == "#":
            while i < n and source[i] != "\n":
                i += 1
            continue

        if ch.isdigit() or (ch == "." and i + 1 < n and source[i + 1].isdigit()):
            start = i
            j = i
            if ch == ".":
                j += 1
            while j < n and source[j].isdigit():
                j += 1
            if j < n and source[j] == ".":
                if j + 1 >= n or not source[j + 1].isdigit():
                    raise LexError("invalid number", start)
                j += 1
                while j < n and source[j].isdigit():
                    j += 1
            if j < n and source[j] in "eE":
                j += 1
                if j < n and source[j] in "+-":
                    j += 1
                if j >= n or not source[j].isdigit():
                    raise LexError("invalid number", start)
                while j < n and source[j].isdigit():
                    j += 1
            number_text = source[start:j]
            if number_text.endswith("."):
                raise LexError("invalid number", start)
            try:
                value = float(number_text)
            except ValueError as exc:  # pragma: no cover - defensive guard
                raise LexError("invalid number", start) from exc
            tokens.append(Token("NUMBER", value, start))
            i = j
            continue

        if ch == '"':
            start = i
            i += 1
            chars: list[str] = []
            while i < n:
                c = source[i]
                if c == '"':
                    i += 1
                    tokens.append(Token("STRING", "".join(chars), start))
                    break
                if c == "\\":
                    if i + 1 >= n:
                        raise LexError("unterminated string", start)
                    esc = source[i + 1]
                    if esc not in ESCAPES:
                        raise LexError(f"invalid escape: \\{esc}", i)
                    chars.append(ESCAPES[esc])
                    i += 2
                    continue
                if c in "\r\n":
                    raise LexError("unterminated string", start)
                chars.append(c)
                i += 1
            else:
                raise LexError("unterminated string", start)
            continue

        if ch.isalpha() or ch == "_":
            start = i
            i += 1
            while i < n and (source[i].isalnum() or source[i] == "_"):
                i += 1
            value = source[start:i]
            kind = "KEYWORD" if value in KEYWORDS else "IDENT"
            tokens.append(Token(kind, value, start))
            continue

        if ch in "+-*/% ^(),":
            value = ch
            if ch == " ":
                raise LexError("unexpected character", i)
            if ch == "^":
                tokens.append(Token("OP", value, i))
                i += 1
                continue
            if ch in "+-*/%":
                tokens.append(Token("OP", value, i))
                i += 1
                continue
            if ch == "(":
                tokens.append(Token("OP", "(", i))
                i += 1
                continue
            if ch == ")":
                tokens.append(Token("OP", ")", i))
                i += 1
                continue
            if ch == ",":
                tokens.append(Token("OP", ",", i))
                i += 1
                continue

        if ch in "<>!=":
            start = i
            if ch == "!":
                if i + 1 < n and source[i + 1] == "=":
                    tokens.append(Token("OP", "!=", i))
                    i += 2
                    continue
                raise LexError("unexpected character", i)
            if ch == "=":
                if i + 1 < n and source[i + 1] == "=":
                    tokens.append(Token("OP", "==", i))
                    i += 2
                    continue
                raise LexError("unexpected character", i)
            if ch in "<>":
                if i + 1 < n and source[i + 1] == "=":
                    tokens.append(Token("OP", ch + "=", i))
                    i += 2
                    continue
                tokens.append(Token("OP", ch, i))
                i += 1
                continue

        raise LexError(f"unexpected character: {ch}", i)

    return tokens

from dataclasses import dataclass, field

from .errors import ParseError
from .lexer import Token


@dataclass
class NumberNode:
    value: float


@dataclass
class StringNode:
    value: str


@dataclass
class BoolNode:
    value: bool


@dataclass
class NameNode:
    name: str


@dataclass
class UnaryNode:
    op: str
    operand: object


@dataclass
class BinaryNode:
    op: str
    left: object
    right: object


@dataclass
class CallNode:
    name: str
    args: list[object] = field(default_factory=list)


COMPARATORS = {"==", "!=", "<", "<=", ">", ">="}


class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.index = 0

    def current(self) -> Token | None:
        if self.index >= len(self.tokens):
            return None
        return self.tokens[self.index]

    def advance(self) -> Token:
        token = self.current()
        if token is None:
            raise ParseError("unexpected end of input", None)
        self.index += 1
        return token

    def match_keyword(self, *values: str) -> bool:
        token = self.current()
        if token is None or token.kind != "KEYWORD":
            return False
        if token.value in values:
            self.index += 1
            return True
        return False

    def match_op(self, *values: str) -> bool:
        token = self.current()
        if token is None or token.kind != "OP":
            return False
        if token.value in values:
            self.index += 1
            return True
        return False

    def parse(self):
        if not self.tokens:
            raise ParseError("empty input", 0)
        node = self.parse_expr()
        if self.index != len(self.tokens):
            token = self.current()
            raise ParseError("trailing input", token.position if token else 0)
        return node

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        node = self.parse_and()
        while self.match_keyword("or"):
            node = BinaryNode("or", node, self.parse_and())
        return node

    def parse_and(self):
        node = self.parse_not()
        while self.match_keyword("and"):
            node = BinaryNode("and", node, self.parse_not())
        return node

    def parse_not(self):
        if self.match_keyword("not"):
            return UnaryNode("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        node = self.parse_additive()
        token = self.current()
        if token is not None and token.kind == "OP" and token.value in COMPARATORS:
            if token.value in {"==", "!=", "<", "<=", ">", ">="}:
                op = self.advance().value
                right = self.parse_additive()
                if self.current() is not None and self.current().kind == "OP" and self.current().value in COMPARATORS:
                    raise ParseError("non-associative comparison", self.current().position)
                return BinaryNode(op, node, right)
        return node

    def parse_additive(self):
        node = self.parse_multiplicative()
        while True:
            if self.match_op("+"):
                node = BinaryNode("+", node, self.parse_multiplicative())
            elif self.match_op("-"):
                node = BinaryNode("-", node, self.parse_multiplicative())
            else:
                return node

    def parse_multiplicative(self):
        node = self.parse_unary()
        while True:
            if self.match_op("*"):
                node = BinaryNode("*", node, self.parse_unary())
            elif self.match_op("/"):
                node = BinaryNode("/", node, self.parse_unary())
            elif self.match_op("%"):
                node = BinaryNode("%", node, self.parse_unary())
            else:
                return node

    def parse_unary(self):
        if self.match_op("-"):
            return UnaryNode("-", self.parse_unary())
        return self.parse_power()

    def parse_power(self):
        node = self.parse_primary()
        if self.match_op("^"):
            return BinaryNode("^", node, self.parse_unary())
        return node

    def parse_primary(self):
        token = self.current()
        if token is None:
            raise ParseError("unexpected end of input", None)

        if token.kind == "NUMBER":
            self.advance()
            return NumberNode(float(token.value))

        if token.kind == "STRING":
            self.advance()
            return StringNode(token.value)

        if token.kind == "KEYWORD":
            if token.value == "true":
                self.advance()
                return BoolNode(True)
            if token.value == "false":
                self.advance()
                return BoolNode(False)

        if token.kind == "IDENT":
            name = self.advance().value
            if self.match_op("("):
                args = []
                if not self.match_op(")"):
                    while True:
                        args.append(self.parse_expr())
                        if self.match_op(","):
                            continue
                        if not self.match_op(")"):
                            raise ParseError("expected ')'", self.current().position if self.current() else 0)
                        break
                return CallNode(name, args)
            return NameNode(name)

        if self.match_op("("):
            expr = self.parse_expr()
            if not self.match_op(")"):
                raise ParseError("expected ')'", self.current().position if self.current() else 0)
            return expr

        raise ParseError("unexpected token", token.position)


def parse(source: str):
    from .lexer import tokenize

    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()

import math

from .errors import EvalError


def _arity_error(name: str, expected: int, got: int) -> EvalError:
    return EvalError(f"{name}() takes {expected} argument(s), got {got}")


def _require_number(value, name: str):
    if type(value) is not float:
        raise EvalError(f"{name}() requires numbers")
    return value


def _require_bool(value, name: str):
    if type(value) is not bool:
        raise EvalError(f"{name}() requires booleans")
    return value


def _require_string(value, name: str):
    if type(value) is not str:
        raise EvalError(f"{name}() requires strings")
    return value


def builtin_abs(args):
    if len(args) != 1:
        raise _arity_error("abs", 1, len(args))
    value = _require_number(args[0], "abs")
    return abs(value)


def builtin_min(args):
    if not args:
        raise _arity_error("min", 1, 0)
    values = [_require_number(v, "min") for v in args]
    return min(values)


def builtin_max(args):
    if not args:
        raise _arity_error("max", 1, 0)
    values = [_require_number(v, "max") for v in args]
    return max(values)


def builtin_round(args):
    if len(args) not in (1, 2):
        raise _arity_error("round", 1 if len(args) < 2 else 2, len(args))
    x = _require_number(args[0], "round")
    if len(args) == 1:
        return float(round(x))
    n = _require_number(args[1], "round")
    if not n.is_integer():
        raise EvalError("round() requires a whole number for the second argument")
    return float(round(x, int(n)))


def builtin_len(args):
    if len(args) != 1:
        raise _arity_error("len", 1, len(args))
    value = _require_string(args[0], "len")
    return float(len(value))


def builtin_upper(args):
    if len(args) != 1:
        raise _arity_error("upper", 1, len(args))
    value = _require_string(args[0], "upper")
    return value.upper()


def builtin_lower(args):
    if len(args) != 1:
        raise _arity_error("lower", 1, len(args))
    value = _require_string(args[0], "lower")
    return value.lower()


def builtin_str(args):
    if len(args) != 1:
        raise _arity_error("str", 1, len(args))
    return format_value(args[0])


def builtin_num(args):
    if len(args) != 1:
        raise _arity_error("num", 1, len(args))
    value = _require_string(args[0], "num")
    try:
        return float(value.strip())
    except ValueError as exc:
        raise EvalError(f"invalid number: {value!r}") from exc


def builtin_if(args):
    if len(args) != 3:
        raise _arity_error("if", 3, len(args))
    if type(args[0]) is not bool:
        raise EvalError("if() requires a boolean condition")
    return args[1] if args[0] else args[2]


def format_value(value):
    if type(value) is bool:
        return "true" if value else "false"
    if type(value) is float:
        if value.is_integer():
            return str(int(value))
        return repr(value)
    if type(value) is str:
        escaped = value.replace("\\", "\\\\").replace('"', '\\"')
        escaped = escaped.replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t")
        return f'"{escaped}"'
    raise TypeError(f"unsupported value: {value!r}")


BUILTINS = {
    "abs": builtin_abs,
    "min": builtin_min,
    "max": builtin_max,
    "round": builtin_round,
    "len": builtin_len,
    "upper": builtin_upper,
    "lower": builtin_lower,
    "str": builtin_str,
    "num": builtin_num,
    "if": builtin_if,
}

import math

from .builtins import BUILTINS, format_value
from .errors import EvalError
from .parser import BinaryNode, BoolNode, CallNode, NameNode, NumberNode, StringNode, UnaryNode


def _is_bool(value) -> bool:
    return type(value) is bool


def _as_bool(value, context: str) -> bool:
    if not _is_bool(value):
        raise EvalError(f"{context} requires a boolean")
    return value


def _as_number(value, context: str) -> float:
    if type(value) is not float:
        raise EvalError(f"{context} requires numbers")
    return value


def _eval_call(name: str, args, env):
    if name == "if":
        if len(args) != 3:
            raise EvalError(f"if() takes 3 argument(s), got {len(args)}")
        cond = evaluate_node(args[0], env)
        if not _is_bool(cond):
            raise EvalError("if() requires a boolean condition")
        if cond:
            return evaluate_node(args[1], env)
        return evaluate_node(args[2], env)

    if name not in BUILTINS:
        raise EvalError(f"undefined function: {name}")

    evaluated = [evaluate_node(arg, env) for arg in args]
    return BUILTINS[name](evaluated)


def _value_from_env(name: str, env):
    if name not in env:
        raise EvalError(f"undefined variable: {name}")
    value = env[name]
    if type(value) in (float, str, bool):
        return value
    raise EvalError(f"unsupported value for {name}: {value!r}")


def evaluate_node(node, env):
    if isinstance(node, NumberNode):
        return node.value

    if isinstance(node, StringNode):
        return node.value

    if isinstance(node, BoolNode):
        return node.value

    if isinstance(node, NameNode):
        return _value_from_env(node.name, env)

    if isinstance(node, UnaryNode):
        operand = evaluate_node(node.operand, env)
        if node.op == "-":
            if type(operand) is not float:
                raise EvalError("unary minus requires a number")
            return -operand
        if node.op == "not":
            if type(operand) is not bool:
                raise EvalError("not requires a boolean")
            return not operand
        raise EvalError(f"unsupported unary operator: {node.op}")

    if isinstance(node, BinaryNode):
        op = node.op
        if op == "and":
            left = evaluate_node(node.left, env)
            if type(left) is not bool:
                raise EvalError("and requires booleans")
            if not left:
                return False
            right = evaluate_node(node.right, env)
            if type(right) is not bool:
                raise EvalError("and requires booleans")
            return right

        if op == "or":
            left = evaluate_node(node.left, env)
            if type(left) is not bool:
                raise EvalError("or requires booleans")
            if left:
                return True
            right = evaluate_node(node.right, env)
            if type(right) is not bool:
                raise EvalError("or requires booleans")
            return right

        left = evaluate_node(node.left, env)
        right = evaluate_node(node.right, env)

        if op == "+":
            if type(left) is float and type(right) is float:
                return left + right
            if type(left) is str and type(right) is str:
                return left + right
            raise EvalError("+ requires two numbers or two strings")

        if op == "-":
            if type(left) is not float or type(right) is not float:
                raise EvalError("- requires numbers")
            return left - right

        if op == "*":
            if type(left) is not float or type(right) is not float:
                raise EvalError("* requires numbers")
            return left * right

        if op == "/":
            if type(left) is not float or type(right) is not float:
                raise EvalError("/ requires numbers")
            if right == 0.0:
                raise EvalError("division by zero")
            return left / right

        if op == "%":
            if type(left) is not float or type(right) is not float:
                raise EvalError("% requires numbers")
            if right == 0.0:
                raise EvalError("modulo by zero")
            return left % right

        if op == "^":
            if type(left) is not float or type(right) is not float:
                raise EvalError("^ requires numbers")
            try:
                result = left ** right
            except (OverflowError, ValueError):
                raise EvalError("result is not a real number") from None
            if isinstance(result, complex) or not math.isfinite(result):
                raise EvalError("result is not a real number")
            return float(result)

        if op == "==":
            if type(left) is not type(right):
                return False
            return left == right

        if op == "!=":
            if type(left) is not type(right):
                return True
            return left != right

        if op in {"<", "<=", ">", ">="}:
            if type(left) is float and type(right) is float:
                if op == "<":
                    return left < right
                if op == "<=":
                    return left <= right
                if op == ">":
                    return left > right
                return left >= right
            if type(left) is str and type(right) is str:
                if op == "<":
                    return left < right
                if op == "<=":
                    return left <= right
                if op == ">":
                    return left > right
                return left >= right
            raise EvalError("comparison requires numbers or strings")

        raise EvalError(f"unsupported operator: {op}")

    if isinstance(node, CallNode):
        return _eval_call(node.name, node.args, env)

    raise EvalError(f"unsupported node type: {type(node).__name__}")


def evaluate(source: str, env: dict | None = None):
    from .parser import parse

    if env is None:
        local_env = {}
    else:
        local_env = dict(env)
    return evaluate_node(parse(source), local_env)

import re
import sys

from .builtins import format_value
from .errors import MiniLangError
from .evaluator import evaluate


_ASSIGNMENT_RE = re.compile(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(?!=)\s*(.*)\s*$")


def main() -> int:
    env = {}
    for raw_line in sys.stdin:
        line = raw_line.rstrip("\r\n")
        stripped = line.strip()
        if not stripped:
            continue
        if stripped == ":quit":
            return 0
        if stripped == ":vars":
            if not env:
                continue
            for name in sorted(env):
                print(f"{name} = {format_value(env[name])}")
            continue

        match = _ASSIGNMENT_RE.match(line)
        if match:
            name, expr_src = match.groups()
            try:
                value = evaluate(expr_src, env)
            except MiniLangError as exc:
                print(f"error: {exc}")
                continue
            env[name] = value
            continue

        try:
            value = evaluate(line, env)
        except MiniLangError as exc:
            print(f"error: {exc}")
            continue
        print(format_value(value))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

